from fractions import Fraction
from functools import lru_cache
from typing import List

@lru_cache(maxsize=None)
def eulerian(n: int, k: int) -> int:
    if k < 0 or k >= max(n, 1):
        return 0
    if n == 0:
        return 1 if k == 0 else 0
    if k == 0:
        return 1
    return (k + 1) * eulerian(n - 1, k) + (n - k) * eulerian(n - 1, k - 1)

def squared_row(n: int) -> List[int]:
    top = max(n, 1)
    c = [sum(eulerian(n, j) * eulerian(j, k) for j in range(top)) for k in range(top)]
    while len(c) > 1 and c[-1] == 0:
        c.pop()
    return c

Poly = List[Fraction]

def _trim(p: Poly) -> Poly:
    q = list(p)
    while len(q) > 1 and q[-1] == 0:
        q.pop()
    return q

def _deriv(p: Poly) -> Poly:
    return _trim([p[i] * i for i in range(1, len(p))]) if len(p) > 1 else [Fraction(0)]

def _rem(a: Poly, b: Poly) -> Poly:
    a = [Fraction(x) for x in _trim(a)]; b = _trim(b)
    while len(a) >= len(b) and not (len(a) == 1 and a[0] == 0):
        if a[-1] == 0:
            a.pop(); continue
        c = a[-1] / b[-1]; s = len(a) - len(b)
        for i in range(len(b)):
            a[i + s] -= c * b[i]
        a = _trim(a)
        if len(a) < len(b):
            break
    return _trim(a)

def _sturm(p: Poly) -> List[Poly]:
    p = [Fraction(x) for x in _trim(p)]
    seq = [p, _deriv(p)]
    while not (len(_trim(seq[-1])) == 1 and _trim(seq[-1])[0] == 0):
        r = _rem(seq[-2], seq[-1])
        if len(_trim(r)) == 1 and _trim(r)[0] == 0:
            break
        seq.append([-x for x in r])
    return seq

def _eval(p: Poly, x: Fraction) -> Fraction:
    acc = Fraction(0)
    for c in reversed(p):
        acc = acc * x + c
    return acc

def _V(seq: List[Poly], x: Fraction) -> int:
    s = [1 if _eval(p, x) > 0 else -1 for p in seq if _eval(p, x) != 0]
    return sum(1 for i in range(len(s) - 1) if s[i] * s[i + 1] < 0)

def real_roots_in(coeffs: List[int], a: Fraction, b: Fraction) -> int:
    seq = _sturm([Fraction(c) for c in coeffs])
    return _V(seq, a) - _V(seq, b)

if __name__ == "__main__":
    B = Fraction(1 << 40)
    for n in range(3, 11):
        c = squared_row(n)
        deg = len(c) - 1
        total = real_roots_in(c, -B, B)
        neg = real_roots_in(c, -B, Fraction(0))
