from fractions import Fraction
from functools import lru_cache
from typing import List, Tuple

@lru_cache(maxsize=None)
def eulerian(n: int, k: int) -> int:
    if k < 0 or k >= max(n, 1):
        return 0
    if n == 0:
        return 1 if k == 0 else 0
    if k == 0:
        return 1
    return (k + 1) * eulerian(n - 1, k) + (n - k) * eulerian(n - 1, k - 1)

def squared_row(n: int) -> List[int]:
    top = max(n, 1)
    c = [sum(eulerian(n, j) * eulerian(j, k) for j in range(top)) for k in range(top)]
    while len(c) > 1 and c[-1] == 0:
        c.pop()
    return c

def _eval(c: List[float], x: float) -> float:
    acc = 0.0
    for a in reversed(c):
        acc = acc * x + a
    return acc

def real_roots(coeffs: List[int]) -> List[float]:
    """Isolate real roots by bracket scan + bisection (S_n has only simple real roots)."""
    c = [float(a) for a in coeffs]
    roots: List[float] = []
    lo, hi, step = -1000.0, 0.0, 0.01
    x = lo
    prev = _eval(c, x)
    while x < hi:
        nx = x + step
        v = _eval(c, nx)
        if prev == 0.0:
            roots.append(x)
        elif prev * v < 0:
            a, b = x, nx
            for _ in range(80):
                m = 0.5 * (a + b)
                if _eval(c, a) * _eval(c, m) <= 0:
                    b = m
                else:
                    a = m
            roots.append(0.5 * (a + b))
        prev = v
        x = nx
    return sorted(roots)

def interlaces(small: List[float], big: List[float]) -> bool:
    if len(big) != len(small) + 1:
        return False
    return all(big[i] <= small[i] <= big[i + 1] for i in range(len(small)))

if __name__ == "__main__":
    prev: List[float] = []
    for n in range(3, 10):
        r = real_roots(squared_row(n))
        tag = f"interlaces S_{n-1}: {interlaces(prev, r)}" if prev else ""
        print(f"roots S_{n} = {[round(v,4) for v in r]}   {tag}")
        prev = r

