    acc = 0.0
    for a in reversed(c):
        acc = acc * x + a
    return acc

def real_roots(coeffs: List[int]) -> List[float]:
    c = [float(a) for a in coeffs]; roots = []
    x, prev = -2000.0, _eval([float(a) for a in coeffs], -2000.0)
